(()=>{const p={"N04-U01|pilot-serf:usa-abolition-1865":{"category_id":"N04-U01","item_id":"pilot-serf:usa-abolition-1865","question":"Какие события 1865 года обозначают конституционную отмену рабства в США?","title":"Какие события 1865 года обозначают конституционную отмену рабства в США?","text":"Конгресс принял XIII поправку 31 января 1865 года, необходимая ратификация состоялась 6 декабря. Норма запретила рабство и подневольный труд с оговоркой о наказании за преступление. Это другой правовой этап и охват по сравнению с Прокламацией 1863 года. Для международного ориентирования российская реформа 1861 года, американская прокламация и конституционная отмена сохраняются как разные события.","gap":"","coverage_status":"bounded_answer","official_category_exact":"Знать ключевые события, основные даты и этапы истории России и мира.","existing_category_rule_exact":"Ключевые события, даты и этапы России и мира. Мировые события из хронологических блоков учебника учитываются отдельно, даже если они не объясняют российскую реформу причинно.","source_learning_sha256":"36fbf32b9743c62dfa8425424f8b0dd8b6686f15e1efa7ab328e8514bfecf90a","source_item_sha256":"f4c3ad31f34b52bb5daa29f388d41980d4711053e5423472a0285e6707ff3dc9","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"1863 год относится к Прокламации об освобождении, а 1865 — к XIII поправке к Конституции США. Поэтому даты обозначают разные правовые шаги одного процесса, а не два взаимоисключающих ответа.","utf8_sha256":"5cce373e3e5fcd6626856013355f8509b9a792cb966ef3919c3ace7c85cf0e25"},{"paragraph_1based":2,"text":"Национальный архив США указывает: Конгресс принял поправку 31 января 1865 года, необходимая ратификация состоялась 6 декабря. Конституционная норма запретила рабство и подневольный труд с оговоркой о наказании за преступление. Это иной масштаб действия, чем военная прокламация 1863 года.","utf8_sha256":"dbb1bf5421365b4518a7e44825ecf0bdcd8f1bbb976cf8e9f21766ccd8b53687"},{"paragraph_1based":3,"text":"Реформа в России произошла в 1861 году; затем последовали американская прокламация 1863 года и конституционная отмена 1865 года. Такая последовательность помогает сопоставить процессы, не смешивая крепостное право и рабство и не объявляя одинаковыми условия освобождения.","utf8_sha256":"022d1f237e14da6c96f23dbc673844247881d75b66751c9a4ed3613f831a6546"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":123,"quote":"рабство в США сохранялось до 1865 г.","quote_sha256":"cc6313251ef64c38d0046214c85a357ac1878ac06fd23248af4cc5be3eab3d82","source_type":"textbook","source_records":[]}],"basis":["CARD_LEARNING.pilot-serf:usa-abolition-1865.paragraphs","CARD_DATA.items.pilot-serf:usa-abolition-1865.materials","CARD_LEARNING.pilot-serf:usa-abolition-1865.sections"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"context_items":[{"item_id":"pilot-serf:brazil-1888","source_learning_sha256":"84f11540595b420406a574db7896d255e029769f9c6b8af73bf6074001e1ba15","source_item_sha256":"e9625634e16b8c3452a6516fa143d660625f8b4070f9f812bd5fcd0b1717a568"},{"item_id":"pilot-serf:january-1861","source_learning_sha256":"6ca84b3f8fd122643ae388b0e1a333c410083bb921e478dc930a3fb48ba4f947","source_item_sha256":"a0648bd2dc5429c990252b82648afae432ea8fc0601816bc296a7c74415611c7"},{"item_id":"pilot-serf:manifest-1861","source_learning_sha256":"ad55a1be086eaa54e281e351e5687d7c178e20eaa24ae30b107a1bb8dcb85697","source_item_sha256":"897d03bfefa4f2fbd7efa0d687adf0ccda6a889e956a21a76edd179ee6130fe6"},{"item_id":"pilot-serf:peasant-land-bank-1882","source_learning_sha256":"5ceb0c428c3868ac5cf0b9b4b70af3ad5aec844a4541f48173bc30a08fd9eef9","source_item_sha256":"6bb89af4442ee20797e489a74dd73bf2b3551a2c1dc3859db49dc519f92f5e8f"},{"item_id":"pilot-serf:portugal-1869","source_learning_sha256":"f643cab383ddb6f0985943d1b8e78e6a098225ba67a1286eb2fa164a1181aa75","source_item_sha256":"761cce079ab6f3299a9ebde77ed3e4579ace3b1455277564b86063a2cca55798"},{"item_id":"pilot-serf:previous-peasant-measures","source_learning_sha256":"86053c3314e39fcbda339be821c6aaf1eb659670b014f4545d004c3342eb4131","source_item_sha256":"5129b6df4ce64f704c9641b780a57ace4dc178bb8069107a106ec2431e739cb1"},{"item_id":"pilot-serf:redemption-end-1907","source_learning_sha256":"c02d935334cd68456cf7313bf477c12774317faea7e8dcd5dbd7201f3fd2cad0","source_item_sha256":"028e8d1c87e5db1873109c630aaf96e1b2deba7163307d0fa52019bf56fb9ad4"},{"item_id":"pilot-serf:usa-abolition-1865","source_learning_sha256":"36fbf32b9743c62dfa8425424f8b0dd8b6686f15e1efa7ab328e8514bfecf90a","source_item_sha256":"f4c3ad31f34b52bb5daa29f388d41980d4711053e5423472a0285e6707ff3dc9"},{"item_id":"pilot-serf:year-1855","source_learning_sha256":"01a6cd7b48413011b454f7e6867f495182dabe087fc7b1498166ef2c01472db9","source_item_sha256":"6c8a4a69ae302b6ac5e06fb444f83ec6015f088f3f78d7712c10e48f26d7be74"},{"item_id":"pilot-serf:year-1857","source_learning_sha256":"7549ad551ac97259a9b660c209f999d7346c9ca7a324aa939b295dcbb5b98307","source_item_sha256":"e4965947efd70e361261a83aa5f82788191323a92a6f7ee5e30b99bd24adf87e"},{"item_id":"pilot-serf:year-1858","source_learning_sha256":"e09a80514ede19342b43a8957ee491284c5a6312adf301b3fc750c0c8a90e3d3","source_item_sha256":"5919b6e2a3ca67380107032d5d8893513f44caa6cd28f136da8664dbf53129c7"},{"item_id":"pilot-serf:year-1859","source_learning_sha256":"73c5287d4665ee1412e8abfa3b3bbaee5e07ec955913470cebc61165cfc3ef77","source_item_sha256":"bffd0b071513134af5ea81cca4d19e9999242ea33f509f36115b7c4211b76979"},{"item_id":"pilot-serf:year-1881","source_learning_sha256":"992e9b861ecac9bb319522ec307c7dbe58deaedd05827583e58628c09cf7a0ab","source_item_sha256":"ed39554d3e7714a01ea748bd9f966d0fb578396fc9e022fc7f35c9e8702ff9ee"},{"item_id":"pilot-serf:zemsky-chiefs-1889","source_learning_sha256":"bee12cbe6145fb663fc66981a13452a6fe0c97f98034704e0aaafb71a9eebe4d","source_item_sha256":"352f0a276595968092741d6e5b738ab3296528b2b21bc49893b1ca4fd7f08cfa"}],"source_sections":[{"heading":"Ответ: два разных этапа","text":"1863 год относится к Прокламации об освобождении, а 1865 — к XIII поправке к Конституции США. Поэтому даты обозначают разные правовые шаги одного процесса, а не два взаимоисключающих ответа.","utf8_sha256":"5cce373e3e5fcd6626856013355f8509b9a792cb966ef3919c3ace7c85cf0e25"},{"heading":"Что изменилось в 1865 году","text":"Национальный архив США указывает: Конгресс принял поправку 31 января 1865 года, необходимая ратификация состоялась 6 декабря. Конституционная норма запретила рабство и подневольный труд с оговоркой о наказании за преступление. Это иной масштаб действия, чем военная прокламация 1863 года.","utf8_sha256":"dbb1bf5421365b4518a7e44825ecf0bdcd8f1bbb976cf8e9f21766ccd8b53687"},{"heading":"Хронологическое сопоставление","text":"Реформа в России произошла в 1861 году; затем последовали американская прокламация 1863 года и конституционная отмена 1865 года. Такая последовательность помогает сопоставить процессы, не смешивая крепостное право и рабство и не объявляя одинаковыми условия освобождения.","utf8_sha256":"022d1f237e14da6c96f23dbc673844247881d75b66751c9a4ed3613f831a6546"}],"additional_saved_quotes":[]},"N04-U01|pilot-serf:portugal-1869":{"category_id":"N04-U01","item_id":"pilot-serf:portugal-1869","question":"Какой ориентир 1869 года учебник связывает с владениями Португалии?","title":"Какой ориентир 1869 года учебник связывает с владениями Португалии?","text":"Учебник указывает 1869 год как дату отмены рабства во владениях Португалии. Она относится к мировой истории освобождения зависимого населения после российской реформы 1861 года. Нужно сохранить страну, колониальный охват и событие, не превращая близость дат в доказательство прямого влияния России или одинакового устройства реформ.","gap":"Подробные переходные условия и практика во владениях Португалии здесь не реконструированы.","coverage_status":"bounded_example_with_explicit_scope","official_category_exact":"Знать ключевые события, основные даты и этапы истории России и мира.","existing_category_rule_exact":"Ключевые события, даты и этапы России и мира. Мировые события из хронологических блоков учебника учитываются отдельно, даже если они не объясняют российскую реформу причинно.","source_learning_sha256":"f643cab383ddb6f0985943d1b8e78e6a098225ba67a1286eb2fa164a1181aa75","source_item_sha256":"761cce079ab6f3299a9ebde77ed3e4579ace3b1455277564b86063a2cca55798","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"Учебник указывает 1869 год как дату отмены рабства во владениях Португалии. Здесь важно сохранить географическое уточнение: сообщение относится к владениям государства, а не просто к событию внутри его европейской территории.","utf8_sha256":"0d3d255f047236c3d9736609f8e1674917f3befd0cca6b3d26c1c69479518f1f"},{"paragraph_1based":2,"text":"1869 год следует после российской реформы 1861 года. Сопоставление показывает, что освобождение зависимых людей происходило в разных странах в разные сроки; российское событие можно разместить внутри этой более широкой хронологии.","utf8_sha256":"b72c3622f83ffab64735bd7016bea417183442284a00c890d0adace3cebc81f6"},{"paragraph_1based":3,"text":"Крепостная зависимость и рабство — разные исторические институты. Сходство общей направленности изменений не означает одинакового положения людей до реформы или одинаковых условий после неё. Подробности переходного периода требуют дополнительных документов и не добавляются к краткой учебниковой дате без проверки.","utf8_sha256":"1ce70b35cd131446cd1b63b97852c3c6576869accd91598a21b5e7a198544f8c"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":123,"quote":"а в 1869 г. — Португалия","quote_sha256":"be606d42caaf9c1a186a18fa274ac3a822cf7510d0da260b7f4411e70785e962","source_type":"textbook","source_records":[]}],"basis":["CARD_LEARNING.pilot-serf:portugal-1869.paragraphs","CARD_DATA.items.pilot-serf:portugal-1869.materials","CARD_LEARNING.pilot-serf:portugal-1869.sections"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"context_items":[{"item_id":"pilot-serf:brazil-1888","source_learning_sha256":"84f11540595b420406a574db7896d255e029769f9c6b8af73bf6074001e1ba15","source_item_sha256":"e9625634e16b8c3452a6516fa143d660625f8b4070f9f812bd5fcd0b1717a568"},{"item_id":"pilot-serf:january-1861","source_learning_sha256":"6ca84b3f8fd122643ae388b0e1a333c410083bb921e478dc930a3fb48ba4f947","source_item_sha256":"a0648bd2dc5429c990252b82648afae432ea8fc0601816bc296a7c74415611c7"},{"item_id":"pilot-serf:manifest-1861","source_learning_sha256":"ad55a1be086eaa54e281e351e5687d7c178e20eaa24ae30b107a1bb8dcb85697","source_item_sha256":"897d03bfefa4f2fbd7efa0d687adf0ccda6a889e956a21a76edd179ee6130fe6"},{"item_id":"pilot-serf:peasant-land-bank-1882","source_learning_sha256":"5ceb0c428c3868ac5cf0b9b4b70af3ad5aec844a4541f48173bc30a08fd9eef9","source_item_sha256":"6bb89af4442ee20797e489a74dd73bf2b3551a2c1dc3859db49dc519f92f5e8f"},{"item_id":"pilot-serf:portugal-1869","source_learning_sha256":"f643cab383ddb6f0985943d1b8e78e6a098225ba67a1286eb2fa164a1181aa75","source_item_sha256":"761cce079ab6f3299a9ebde77ed3e4579ace3b1455277564b86063a2cca55798"},{"item_id":"pilot-serf:previous-peasant-measures","source_learning_sha256":"86053c3314e39fcbda339be821c6aaf1eb659670b014f4545d004c3342eb4131","source_item_sha256":"5129b6df4ce64f704c9641b780a57ace4dc178bb8069107a106ec2431e739cb1"},{"item_id":"pilot-serf:redemption-end-1907","source_learning_sha256":"c02d935334cd68456cf7313bf477c12774317faea7e8dcd5dbd7201f3fd2cad0","source_item_sha256":"028e8d1c87e5db1873109c630aaf96e1b2deba7163307d0fa52019bf56fb9ad4"},{"item_id":"pilot-serf:usa-abolition-1865","source_learning_sha256":"36fbf32b9743c62dfa8425424f8b0dd8b6686f15e1efa7ab328e8514bfecf90a","source_item_sha256":"f4c3ad31f34b52bb5daa29f388d41980d4711053e5423472a0285e6707ff3dc9"},{"item_id":"pilot-serf:year-1855","source_learning_sha256":"01a6cd7b48413011b454f7e6867f495182dabe087fc7b1498166ef2c01472db9","source_item_sha256":"6c8a4a69ae302b6ac5e06fb444f83ec6015f088f3f78d7712c10e48f26d7be74"},{"item_id":"pilot-serf:year-1857","source_learning_sha256":"7549ad551ac97259a9b660c209f999d7346c9ca7a324aa939b295dcbb5b98307","source_item_sha256":"e4965947efd70e361261a83aa5f82788191323a92a6f7ee5e30b99bd24adf87e"},{"item_id":"pilot-serf:year-1858","source_learning_sha256":"e09a80514ede19342b43a8957ee491284c5a6312adf301b3fc750c0c8a90e3d3","source_item_sha256":"5919b6e2a3ca67380107032d5d8893513f44caa6cd28f136da8664dbf53129c7"},{"item_id":"pilot-serf:year-1859","source_learning_sha256":"73c5287d4665ee1412e8abfa3b3bbaee5e07ec955913470cebc61165cfc3ef77","source_item_sha256":"bffd0b071513134af5ea81cca4d19e9999242ea33f509f36115b7c4211b76979"},{"item_id":"pilot-serf:year-1881","source_learning_sha256":"992e9b861ecac9bb319522ec307c7dbe58deaedd05827583e58628c09cf7a0ab","source_item_sha256":"ed39554d3e7714a01ea748bd9f966d0fb578396fc9e022fc7f35c9e8702ff9ee"},{"item_id":"pilot-serf:zemsky-chiefs-1889","source_learning_sha256":"bee12cbe6145fb663fc66981a13452a6fe0c97f98034704e0aaafb71a9eebe4d","source_item_sha256":"352f0a276595968092741d6e5b738ab3296528b2b21bc49893b1ca4fd7f08cfa"}],"source_sections":[{"heading":"Дата и событие","text":"Учебник указывает 1869 год как дату отмены рабства во владениях Португалии. Здесь важно сохранить географическое уточнение: сообщение относится к владениям государства, а не просто к событию внутри его европейской территории.","utf8_sha256":"0d3d255f047236c3d9736609f8e1674917f3befd0cca6b3d26c1c69479518f1f"},{"heading":"Место в последовательности","text":"1869 год следует после российской реформы 1861 года. Сопоставление показывает, что освобождение зависимых людей происходило в разных странах в разные сроки; российское событие можно разместить внутри этой более широкой хронологии.","utf8_sha256":"b72c3622f83ffab64735bd7016bea417183442284a00c890d0adace3cebc81f6"},{"heading":"Что не следует смешивать","text":"Крепостная зависимость и рабство — разные исторические институты. Сходство общей направленности изменений не означает одинакового положения людей до реформы или одинаковых условий после неё. Подробности переходного периода требуют дополнительных документов и не добавляются к краткой учебниковой дате без проверки.","utf8_sha256":"1ce70b35cd131446cd1b63b97852c3c6576869accd91598a21b5e7a198544f8c"}],"additional_saved_quotes":[]},"N04-U01|pilot-serf:year-1881":{"category_id":"N04-U01","item_id":"pilot-serf:year-1881","question":"Какое российское мероприятие 1881 года продолжало решение земельного вопроса?","title":"Какое российское мероприятие 1881 года продолжало решение земельного вопроса?","text":"1881 год — издание указа о переводе остававшихся временнообязанными крестьян на обязательный выкуп. Это изменение земельных обязательств лично свободных людей, а не повторное освобождение от собственности помещика. Дату принятия решения нужно отличать от начала исполнения и от последующей отмены платежей в 1907 году.","gap":"","coverage_status":"bounded_answer","official_category_exact":"Знать ключевые события, основные даты и этапы истории России и мира.","existing_category_rule_exact":"Ключевые события, даты и этапы России и мира. Мировые события из хронологических блоков учебника учитываются отдельно, даже если они не объясняют российскую реформу причинно.","source_learning_sha256":"992e9b861ecac9bb319522ec307c7dbe58deaedd05827583e58628c09cf7a0ab","source_item_sha256":"ed39554d3e7714a01ea748bd9f966d0fb578396fc9e022fc7f35c9e8702ff9ee","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"Учебник датирует указ об обязательном выкупе 1881 годом. Дата издания указа не подменяется датой начала исполнения.","utf8_sha256":"8f22c57cde807a2fd288d2c86710ae68beb5c739a773dfdcc7a678ec2cf714bc"},{"paragraph_1based":2,"text":"Манифест 1861 года и указ 1881 года решали разные стороны крестьянского вопроса. Первый связан с личным освобождением, второй — с переводом сохранявших повинности временнообязанных крестьян на выкуп. Двадцатилетний промежуток показывает, почему отмена личной зависимости не равнялась мгновенному завершению земельного преобразования.","utf8_sha256":"88f19ea685974868e95ccaa43d6052337cc690da245a0433525ecd4981aca5b6"},{"paragraph_1based":3,"text":"Обязательный выкуп касался тех крестьян, которые ещё оставались во временнообязанном состоянии. Это продолжение решения земельного вопроса, а не повторное предоставление личной свободы. Для различения дат полезно помнить три разных события: освобождение в 1861 году, указ об обязательном выкупе в 1881 году и отмену выкупных платежей в 1907 году.","utf8_sha256":"44260a5f0e76f02c81d0c12cd549eecf7c1ceb0e11d037d119a1afd20fccefcf"},{"paragraph_1based":4,"text":"В 1861 году менялся личный статус, в 1881 году принято решение об обязательном выкупе для остававшихся временнообязанными, а в 1907 году прекращались выкупные платежи. События относятся к разным сторонам длительного преобразования. Поэтому двадцать лет между первыми двумя датами не означают отсутствие свободы всё это время: они показывают сохранение нерешённых земельных отношений у части крестьян после Манифеста.","utf8_sha256":"4ab94cbb56e918d0fe755b7a379f9b0bd1ac8e555dac8e32a16c9a25795830d3"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":128,"quote":"Лишь в 1881 г. был издан указ о переводе \nвсех временнообязанных крестьян на обязательный выкуп","quote_sha256":"9a02529eb2d2d1b8d8b573b72d08b9b85384f063f05966d42935e296b532c466","source_type":"textbook","source_records":[]}],"basis":["CARD_LEARNING.pilot-serf:year-1881.paragraphs","CARD_DATA.items.pilot-serf:year-1881.materials","CARD_LEARNING.pilot-serf:year-1881.sections"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"context_items":[{"item_id":"pilot-serf:brazil-1888","source_learning_sha256":"84f11540595b420406a574db7896d255e029769f9c6b8af73bf6074001e1ba15","source_item_sha256":"e9625634e16b8c3452a6516fa143d660625f8b4070f9f812bd5fcd0b1717a568"},{"item_id":"pilot-serf:january-1861","source_learning_sha256":"6ca84b3f8fd122643ae388b0e1a333c410083bb921e478dc930a3fb48ba4f947","source_item_sha256":"a0648bd2dc5429c990252b82648afae432ea8fc0601816bc296a7c74415611c7"},{"item_id":"pilot-serf:manifest-1861","source_learning_sha256":"ad55a1be086eaa54e281e351e5687d7c178e20eaa24ae30b107a1bb8dcb85697","source_item_sha256":"897d03bfefa4f2fbd7efa0d687adf0ccda6a889e956a21a76edd179ee6130fe6"},{"item_id":"pilot-serf:peasant-land-bank-1882","source_learning_sha256":"5ceb0c428c3868ac5cf0b9b4b70af3ad5aec844a4541f48173bc30a08fd9eef9","source_item_sha256":"6bb89af4442ee20797e489a74dd73bf2b3551a2c1dc3859db49dc519f92f5e8f"},{"item_id":"pilot-serf:portugal-1869","source_learning_sha256":"f643cab383ddb6f0985943d1b8e78e6a098225ba67a1286eb2fa164a1181aa75","source_item_sha256":"761cce079ab6f3299a9ebde77ed3e4579ace3b1455277564b86063a2cca55798"},{"item_id":"pilot-serf:previous-peasant-measures","source_learning_sha256":"86053c3314e39fcbda339be821c6aaf1eb659670b014f4545d004c3342eb4131","source_item_sha256":"5129b6df4ce64f704c9641b780a57ace4dc178bb8069107a106ec2431e739cb1"},{"item_id":"pilot-serf:redemption-end-1907","source_learning_sha256":"c02d935334cd68456cf7313bf477c12774317faea7e8dcd5dbd7201f3fd2cad0","source_item_sha256":"028e8d1c87e5db1873109c630aaf96e1b2deba7163307d0fa52019bf56fb9ad4"},{"item_id":"pilot-serf:usa-abolition-1865","source_learning_sha256":"36fbf32b9743c62dfa8425424f8b0dd8b6686f15e1efa7ab328e8514bfecf90a","source_item_sha256":"f4c3ad31f34b52bb5daa29f388d41980d4711053e5423472a0285e6707ff3dc9"},{"item_id":"pilot-serf:year-1855","source_learning_sha256":"01a6cd7b48413011b454f7e6867f495182dabe087fc7b1498166ef2c01472db9","source_item_sha256":"6c8a4a69ae302b6ac5e06fb444f83ec6015f088f3f78d7712c10e48f26d7be74"},{"item_id":"pilot-serf:year-1857","source_learning_sha256":"7549ad551ac97259a9b660c209f999d7346c9ca7a324aa939b295dcbb5b98307","source_item_sha256":"e4965947efd70e361261a83aa5f82788191323a92a6f7ee5e30b99bd24adf87e"},{"item_id":"pilot-serf:year-1858","source_learning_sha256":"e09a80514ede19342b43a8957ee491284c5a6312adf301b3fc750c0c8a90e3d3","source_item_sha256":"5919b6e2a3ca67380107032d5d8893513f44caa6cd28f136da8664dbf53129c7"},{"item_id":"pilot-serf:year-1859","source_learning_sha256":"73c5287d4665ee1412e8abfa3b3bbaee5e07ec955913470cebc61165cfc3ef77","source_item_sha256":"bffd0b071513134af5ea81cca4d19e9999242ea33f509f36115b7c4211b76979"},{"item_id":"pilot-serf:year-1881","source_learning_sha256":"992e9b861ecac9bb319522ec307c7dbe58deaedd05827583e58628c09cf7a0ab","source_item_sha256":"ed39554d3e7714a01ea748bd9f966d0fb578396fc9e022fc7f35c9e8702ff9ee"},{"item_id":"pilot-serf:zemsky-chiefs-1889","source_learning_sha256":"bee12cbe6145fb663fc66981a13452a6fe0c97f98034704e0aaafb71a9eebe4d","source_item_sha256":"352f0a276595968092741d6e5b738ab3296528b2b21bc49893b1ca4fd7f08cfa"}],"source_sections":[{"heading":"Указ и начало обязательного выкупа","text":"28 декабря 1881 года был издан указ об обязательном выкупе. По его пункту 1 остававшиеся временнообязанными бывшие помещичьи крестьяне в губерниях, где действовали Великороссийское и Малороссийское местные положения, переводились на выкуп с 1 января 1883 года. Поэтому 1881 — дата решения, 1883 — начало установленного им перевода; это не новая отмена личной зависимости.","utf8_sha256":"2fb298f46b0288d1fd87d5c3a9345fc097822ca635d6d4e4b7a319c10b69c704"},{"heading":"Последовательность земельного вопроса","text":"1861 — личное освобождение и условия земельных отношений; 1881 — указ; 1883 — его осуществление для указанных в нём крестьян; 1907 — прекращение выкупных платежей. В учебниковом хронологическом задании порядок событий остаётся 4–1–2–3, но формулировка о переводе не должна превращать 1881 год в дату начала исполнения.","utf8_sha256":"655caedd74bde447207c356570d75e3bb317e3cbe145a504eb78395fa7f29528"}],"additional_saved_quotes":[{"sourceKey":"1881_decree","kind":"Фрагмент источника","sourceType":"external","sourceTitle":"Указ 28 декабря 1881 года о выкупе наделов","sourceUrl":"https://istmat.org/node/33360","page":"","section":"ПСЗ, собрание III, том 1, № 575, пункт 1","quote":"перевести на выкуп и причислить к разряду крестьян-собственников с 1 января 1883 года."}]},"N04-U01|pilot-serf:peasant-land-bank-1882":{"category_id":"N04-U01","item_id":"pilot-serf:peasant-land-bank-1882","question":"Какое учреждение появилось в 1882 году и с какой задачей связано?","title":"Какое учреждение появилось в 1882 году и с какой задачей связано?","text":"В 1882 году учреждён Крестьянский поземельный банк, помогавший крестьянам покупать частновладельческие земли посредством долгосрочных ссуд. Это последующий этап развития землевладения при Александре III. Кредит на покупку земли через банк нужно отличать от первоначальной выкупной операции 1861 года и указа об обязательном выкупе 1881 года.","gap":"","coverage_status":"bounded_answer","official_category_exact":"Знать ключевые события, основные даты и этапы истории России и мира.","existing_category_rule_exact":"Ключевые события, даты и этапы России и мира. Мировые события из хронологических блоков учебника учитываются отдельно, даже если они не объясняют российскую реформу причинно.","source_learning_sha256":"5ceb0c428c3868ac5cf0b9b4b70af3ad5aec844a4541f48173bc30a08fd9eef9","source_item_sha256":"6bb89af4442ee20797e489a74dd73bf2b3551a2c1dc3859db49dc519f92f5e8f","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"После отмены крепостного права земельный вопрос продолжал существовать. Учреждённый в 1882 году Крестьянский поземельный банк помогал приобретать частновладельческие земли посредством долгосрочных ссуд. Его деятельность относится к последующему развитию крестьянского землевладения.","utf8_sha256":"cdb6076243fb67270daff2d43d19b0d4f8c640923edea1f8de3f1fc4f9488ee7"},{"paragraph_1based":2,"text":"Кредит на покупку земли через банк и предусмотренная реформой 1861 года выкупная операция — разные механизмы. Наличие слова«крестьянский» или государственного финансирования не делает их одним учреждением или одним событием; при ответе нужно назвать 1882 год, банк и покупку земли.","utf8_sha256":"36e88cf24578bc94932965a05ef2d60846c53199723cd18d97039464c80c9353"},{"paragraph_1based":3,"text":"В официальной демоверсии ЕГЭ 2025 № 20 Крестьянский поземельный банк назван в ключе как факт, которым можно подтвердить внимание Александра III к финансовой сфере. Для сравнения ему сопоставляется финансовая реформа Е. Ф. Канкрина при Николае I.","utf8_sha256":"9e4322011aa8540f66d86d3ef203fbd9c11d7a25387c21b96f827e569ab0accd"},{"paragraph_1based":4,"text":"Тезис должен задавать общий признак двух политик, а обоснование — конкретизировать его фактами. Одного повторения «оба развивали финансовую сферу» недостаточно.","utf8_sha256":"571fe2f9ad0047abf9a02acef5136e264bf6fb6baf275a2b0553eefd8976300c"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1mQen0T4DHwGg8-CziUe8hPo7mqy59p31/view?usp=drivesdk","page":1,"quote":"Крестьянский поземельный банк","quote_sha256":"93e097f54e68edb72607c02fa0ad4af39b1849ba4c71dfe34f2e8a62644a0cd2","source_type":"reference","source_records":["reference-v19:page:4dc4da52-6cb6-50b8-b58d-d08dcfdab739:1"]}],"basis":["CARD_LEARNING.pilot-serf:peasant-land-bank-1882.paragraphs","CARD_DATA.items.pilot-serf:peasant-land-bank-1882.materials","CARD_LEARNING.pilot-serf:peasant-land-bank-1882.sections"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"context_items":[{"item_id":"pilot-serf:brazil-1888","source_learning_sha256":"84f11540595b420406a574db7896d255e029769f9c6b8af73bf6074001e1ba15","source_item_sha256":"e9625634e16b8c3452a6516fa143d660625f8b4070f9f812bd5fcd0b1717a568"},{"item_id":"pilot-serf:january-1861","source_learning_sha256":"6ca84b3f8fd122643ae388b0e1a333c410083bb921e478dc930a3fb48ba4f947","source_item_sha256":"a0648bd2dc5429c990252b82648afae432ea8fc0601816bc296a7c74415611c7"},{"item_id":"pilot-serf:manifest-1861","source_learning_sha256":"ad55a1be086eaa54e281e351e5687d7c178e20eaa24ae30b107a1bb8dcb85697","source_item_sha256":"897d03bfefa4f2fbd7efa0d687adf0ccda6a889e956a21a76edd179ee6130fe6"},{"item_id":"pilot-serf:peasant-land-bank-1882","source_learning_sha256":"5ceb0c428c3868ac5cf0b9b4b70af3ad5aec844a4541f48173bc30a08fd9eef9","source_item_sha256":"6bb89af4442ee20797e489a74dd73bf2b3551a2c1dc3859db49dc519f92f5e8f"},{"item_id":"pilot-serf:portugal-1869","source_learning_sha256":"f643cab383ddb6f0985943d1b8e78e6a098225ba67a1286eb2fa164a1181aa75","source_item_sha256":"761cce079ab6f3299a9ebde77ed3e4579ace3b1455277564b86063a2cca55798"},{"item_id":"pilot-serf:previous-peasant-measures","source_learning_sha256":"86053c3314e39fcbda339be821c6aaf1eb659670b014f4545d004c3342eb4131","source_item_sha256":"5129b6df4ce64f704c9641b780a57ace4dc178bb8069107a106ec2431e739cb1"},{"item_id":"pilot-serf:redemption-end-1907","source_learning_sha256":"c02d935334cd68456cf7313bf477c12774317faea7e8dcd5dbd7201f3fd2cad0","source_item_sha256":"028e8d1c87e5db1873109c630aaf96e1b2deba7163307d0fa52019bf56fb9ad4"},{"item_id":"pilot-serf:usa-abolition-1865","source_learning_sha256":"36fbf32b9743c62dfa8425424f8b0dd8b6686f15e1efa7ab328e8514bfecf90a","source_item_sha256":"f4c3ad31f34b52bb5daa29f388d41980d4711053e5423472a0285e6707ff3dc9"},{"item_id":"pilot-serf:year-1855","source_learning_sha256":"01a6cd7b48413011b454f7e6867f495182dabe087fc7b1498166ef2c01472db9","source_item_sha256":"6c8a4a69ae302b6ac5e06fb444f83ec6015f088f3f78d7712c10e48f26d7be74"},{"item_id":"pilot-serf:year-1857","source_learning_sha256":"7549ad551ac97259a9b660c209f999d7346c9ca7a324aa939b295dcbb5b98307","source_item_sha256":"e4965947efd70e361261a83aa5f82788191323a92a6f7ee5e30b99bd24adf87e"},{"item_id":"pilot-serf:year-1858","source_learning_sha256":"e09a80514ede19342b43a8957ee491284c5a6312adf301b3fc750c0c8a90e3d3","source_item_sha256":"5919b6e2a3ca67380107032d5d8893513f44caa6cd28f136da8664dbf53129c7"},{"item_id":"pilot-serf:year-1859","source_learning_sha256":"73c5287d4665ee1412e8abfa3b3bbaee5e07ec955913470cebc61165cfc3ef77","source_item_sha256":"bffd0b071513134af5ea81cca4d19e9999242ea33f509f36115b7c4211b76979"},{"item_id":"pilot-serf:year-1881","source_learning_sha256":"992e9b861ecac9bb319522ec307c7dbe58deaedd05827583e58628c09cf7a0ab","source_item_sha256":"ed39554d3e7714a01ea748bd9f966d0fb578396fc9e022fc7f35c9e8702ff9ee"},{"item_id":"pilot-serf:zemsky-chiefs-1889","source_learning_sha256":"bee12cbe6145fb663fc66981a13452a6fe0c97f98034704e0aaafb71a9eebe4d","source_item_sha256":"352f0a276595968092741d6e5b738ab3296528b2b21bc49893b1ca4fd7f08cfa"}],"source_sections":[{"heading":"Содержание","text":"После отмены крепостного права земельный вопрос продолжал существовать. Учреждённый в 1882 году Крестьянский поземельный банк помогал приобретать частновладельческие земли посредством долгосрочных ссуд. Его деятельность относится к последующему развитию крестьянского землевладения.","utf8_sha256":"cdb6076243fb67270daff2d43d19b0d4f8c640923edea1f8de3f1fc4f9488ee7"},{"heading":"Связь с темой и различия","text":"Кредит на покупку земли через банк и предусмотренная реформой 1861 года выкупная операция — разные механизмы. Наличие слова«крестьянский» или государственного финансирования не делает их одним учреждением или одним событием; при ответе нужно назвать 1882 год, банк и покупку земли.","utf8_sha256":"36e88cf24578bc94932965a05ef2d60846c53199723cd18d97039464c80c9353"},{"heading":"Банк как факт для сравнительного аргумента","text":"В официальной демоверсии ЕГЭ 2025 № 20 Крестьянский поземельный банк назван в ключе как факт, которым можно подтвердить внимание Александра III к финансовой сфере. Для сравнения ему сопоставляется финансовая реформа Е. Ф. Канкрина при Николае I. Тезис должен задавать общий признак двух политик, а обоснование — конкретизировать его фактами. Одного повторения «оба развивали финансовую сферу» недостаточно.","utf8_sha256":"d3e96227a8ac8b2ebe99f270f05a257b23212f679c67153bc5f7e78e6558eac0"}],"additional_saved_quotes":[]},"N04-U01|pilot-serf:brazil-1888":{"category_id":"N04-U01","item_id":"pilot-serf:brazil-1888","question":"Какое событие мировой истории соответствует бразильскому ориентиру 1888 года?","title":"Какое событие мировой истории соответствует бразильскому ориентиру 1888 года?","text":"1888 год — отмена рабства в Бразилии по мировой части таблицы учебника. Она показывает, что национальные преобразования происходили в разные сроки: позже российского Манифеста 1861 года и американской конституционной отмены 1865 года. Совпадение общей направленности освобождения не делает рабство и российское крепостное право одинаковыми институтами.","gap":"Условия бразильского закона по одной хронологической строке не реконструируются.","coverage_status":"bounded_example_with_explicit_scope","official_category_exact":"Знать ключевые события, основные даты и этапы истории России и мира.","existing_category_rule_exact":"Ключевые события, даты и этапы России и мира. Мировые события из хронологических блоков учебника учитываются отдельно, даже если они не объясняют российскую реформу причинно.","source_learning_sha256":"84f11540595b420406a574db7896d255e029769f9c6b8af73bf6074001e1ba15","source_item_sha256":"e9625634e16b8c3452a6516fa143d660625f8b4070f9f812bd5fcd0b1717a568","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"В мировой части таблицы страницы 127 указан 1888 год — отмена рабства в Бразилии. Элемент сохраняет название страны, дату и событие как единое соответствие.","utf8_sha256":"5911c599794677b713d770cf2cd656c293d31663e14bdadbeabc8ca73d5f2bc9"},{"paragraph_1based":2,"text":"Бразильское событие произошло на 27 лет позже реформы 1861 года в России и на 23 года позже конституционной отмены рабства в США. Такой расчёт показывает разницу сроков, а не степень сходства общественных систем.","utf8_sha256":"bcb45acbc3401528b81494c1c68d42cce93264c573d95b9ad6ad5ec31fd80477"},{"paragraph_1based":3,"text":"Примеры разных стран показывают длительность и неравномерность процесса освобождения. При объяснении необходимо различать рабство и крепостное право; подробности бразильского закона нельзя восстанавливать только по краткой строке учебника.","utf8_sha256":"a26d5eefdb77f6d317c9fa345f39fd0f9a91e6bc70124f7b563c89268cbe5af4"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":127,"quote":"1888 г. — отмена рабства в Бразилии","quote_sha256":"94a12f965cb7639557e1c6fda0553109d680bd7ab46e4b8b3785c5605a4736f0","source_type":"textbook","source_records":[]}],"basis":["CARD_LEARNING.pilot-serf:brazil-1888.paragraphs","CARD_DATA.items.pilot-serf:brazil-1888.materials","CARD_LEARNING.pilot-serf:brazil-1888.sections"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"context_items":[{"item_id":"pilot-serf:brazil-1888","source_learning_sha256":"84f11540595b420406a574db7896d255e029769f9c6b8af73bf6074001e1ba15","source_item_sha256":"e9625634e16b8c3452a6516fa143d660625f8b4070f9f812bd5fcd0b1717a568"},{"item_id":"pilot-serf:january-1861","source_learning_sha256":"6ca84b3f8fd122643ae388b0e1a333c410083bb921e478dc930a3fb48ba4f947","source_item_sha256":"a0648bd2dc5429c990252b82648afae432ea8fc0601816bc296a7c74415611c7"},{"item_id":"pilot-serf:manifest-1861","source_learning_sha256":"ad55a1be086eaa54e281e351e5687d7c178e20eaa24ae30b107a1bb8dcb85697","source_item_sha256":"897d03bfefa4f2fbd7efa0d687adf0ccda6a889e956a21a76edd179ee6130fe6"},{"item_id":"pilot-serf:peasant-land-bank-1882","source_learning_sha256":"5ceb0c428c3868ac5cf0b9b4b70af3ad5aec844a4541f48173bc30a08fd9eef9","source_item_sha256":"6bb89af4442ee20797e489a74dd73bf2b3551a2c1dc3859db49dc519f92f5e8f"},{"item_id":"pilot-serf:portugal-1869","source_learning_sha256":"f643cab383ddb6f0985943d1b8e78e6a098225ba67a1286eb2fa164a1181aa75","source_item_sha256":"761cce079ab6f3299a9ebde77ed3e4579ace3b1455277564b86063a2cca55798"},{"item_id":"pilot-serf:previous-peasant-measures","source_learning_sha256":"86053c3314e39fcbda339be821c6aaf1eb659670b014f4545d004c3342eb4131","source_item_sha256":"5129b6df4ce64f704c9641b780a57ace4dc178bb8069107a106ec2431e739cb1"},{"item_id":"pilot-serf:redemption-end-1907","source_learning_sha256":"c02d935334cd68456cf7313bf477c12774317faea7e8dcd5dbd7201f3fd2cad0","source_item_sha256":"028e8d1c87e5db1873109c630aaf96e1b2deba7163307d0fa52019bf56fb9ad4"},{"item_id":"pilot-serf:usa-abolition-1865","source_learning_sha256":"36fbf32b9743c62dfa8425424f8b0dd8b6686f15e1efa7ab328e8514bfecf90a","source_item_sha256":"f4c3ad31f34b52bb5daa29f388d41980d4711053e5423472a0285e6707ff3dc9"},{"item_id":"pilot-serf:year-1855","source_learning_sha256":"01a6cd7b48413011b454f7e6867f495182dabe087fc7b1498166ef2c01472db9","source_item_sha256":"6c8a4a69ae302b6ac5e06fb444f83ec6015f088f3f78d7712c10e48f26d7be74"},{"item_id":"pilot-serf:year-1857","source_learning_sha256":"7549ad551ac97259a9b660c209f999d7346c9ca7a324aa939b295dcbb5b98307","source_item_sha256":"e4965947efd70e361261a83aa5f82788191323a92a6f7ee5e30b99bd24adf87e"},{"item_id":"pilot-serf:year-1858","source_learning_sha256":"e09a80514ede19342b43a8957ee491284c5a6312adf301b3fc750c0c8a90e3d3","source_item_sha256":"5919b6e2a3ca67380107032d5d8893513f44caa6cd28f136da8664dbf53129c7"},{"item_id":"pilot-serf:year-1859","source_learning_sha256":"73c5287d4665ee1412e8abfa3b3bbaee5e07ec955913470cebc61165cfc3ef77","source_item_sha256":"bffd0b071513134af5ea81cca4d19e9999242ea33f509f36115b7c4211b76979"},{"item_id":"pilot-serf:year-1881","source_learning_sha256":"992e9b861ecac9bb319522ec307c7dbe58deaedd05827583e58628c09cf7a0ab","source_item_sha256":"ed39554d3e7714a01ea748bd9f966d0fb578396fc9e022fc7f35c9e8702ff9ee"},{"item_id":"pilot-serf:zemsky-chiefs-1889","source_learning_sha256":"bee12cbe6145fb663fc66981a13452a6fe0c97f98034704e0aaafb71a9eebe4d","source_item_sha256":"352f0a276595968092741d6e5b738ab3296528b2b21bc49893b1ca4fd7f08cfa"}],"source_sections":[{"heading":"Дата и событие","text":"В мировой части таблицы страницы 127 указан 1888 год — отмена рабства в Бразилии. Элемент сохраняет название страны, дату и событие как единое соответствие.","utf8_sha256":"5911c599794677b713d770cf2cd656c293d31663e14bdadbeabc8ca73d5f2bc9"},{"heading":"Сопоставление","text":"Бразильское событие произошло на 27 лет позже реформы 1861 года в России и на 23 года позже конституционной отмены рабства в США. Такой расчёт показывает разницу сроков, а не степень сходства общественных систем.","utf8_sha256":"bcb45acbc3401528b81494c1c68d42cce93264c573d95b9ad6ad5ec31fd80477"},{"heading":"Исторический смысл","text":"Примеры разных стран показывают длительность и неравномерность процесса освобождения. При объяснении необходимо различать рабство и крепостное право; подробности бразильского закона нельзя восстанавливать только по краткой строке учебника.","utf8_sha256":"a26d5eefdb77f6d317c9fa345f39fd0f9a91e6bc70124f7b563c89268cbe5af4"}],"additional_saved_quotes":[]},"N04-U01|pilot-serf:zemsky-chiefs-1889":{"category_id":"N04-U01","item_id":"pilot-serf:zemsky-chiefs-1889","question":"Какое изменение устройства крестьянской жизни относится к 1889 году?","title":"Какое изменение устройства крестьянской жизни относится к 1889 году?","text":"Положение о земских участковых начальниках 1889 года усилило административный надзор за крестьянскими учреждениями. Начальник был назначаемым должностным лицом; например, утверждал избранного волостного старшину. Это последующая мера государственного контроля, которую нельзя смешивать с учреждением выборного земства, сельским сходом или мировыми посредниками времени освобождения.","gap":"","coverage_status":"bounded_answer","official_category_exact":"Знать ключевые события, основные даты и этапы истории России и мира.","existing_category_rule_exact":"Ключевые события, даты и этапы России и мира. Мировые события из хронологических блоков учебника учитываются отдельно, даже если они не объясняют российскую реформу причинно.","source_learning_sha256":"bee12cbe6145fb663fc66981a13452a6fe0c97f98034704e0aaafb71a9eebe4d","source_item_sha256":"352f0a276595968092741d6e5b738ab3296528b2b21bc49893b1ca4fd7f08cfa","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"Земский участковый начальник был назначаемым должностным лицом. Положение 1889 года усилило административный надзор за крестьянскими учреждениями; например, избранные волостные старшины подлежали утверждению земского начальника. Таким образом, выборность внутри крестьянского общества сочеталась с контролем государственной власти.","utf8_sha256":"a0a91d352a13757756585a630dbfecb1cb9f9cc23d94d6c4f23f48ca86ad1b95"},{"paragraph_1based":2,"text":"Этот институт относится к последующей истории устройства крестьянской жизни после 1861 года. Его нельзя смешивать с сельским или волостным сходом, выборным земством либо мировым посредником времени проведения реформы: различаются способ назначения, полномочия и время появления.","utf8_sha256":"5c3919eb0053167af224b2c6869207b90a877c9c2132dc1e99983f0267327f75"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1FUhGrkkRawwrZjKDyA9JBOb7ZrXpP9-e/view?usp=drivesdk","page":4,"quote":"ЗЕМСКИХ УЧАСТКОВЫХ НАЧАЛЬНИКОВ","quote_sha256":"e448e5f5bc2479086d5ff56265cd6126014f3f2287e18b4c0daadfcf3959c783","source_type":"reference","source_records":["reference-v19:page:1c04c5a1-6e80-5f06-81cc-eb8a28c7a4fe:4"]},{"source_url":"https://drive.google.com/file/d/1mQen0T4DHwGg8-CziUe8hPo7mqy59p31/view?usp=drivesdk","page":5,"quote":"Земский начальник","quote_sha256":"5b177a3fd68a0767d815ce37c1951f9908c4102502d977d812898082c88ab864","source_type":"reference","source_records":["reference-v19:page:4dc4da52-6cb6-50b8-b58d-d08dcfdab739:5"]}],"basis":["CARD_LEARNING.pilot-serf:zemsky-chiefs-1889.paragraphs","CARD_DATA.items.pilot-serf:zemsky-chiefs-1889.materials","CARD_LEARNING.pilot-serf:zemsky-chiefs-1889.sections"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"context_items":[{"item_id":"pilot-serf:brazil-1888","source_learning_sha256":"84f11540595b420406a574db7896d255e029769f9c6b8af73bf6074001e1ba15","source_item_sha256":"e9625634e16b8c3452a6516fa143d660625f8b4070f9f812bd5fcd0b1717a568"},{"item_id":"pilot-serf:january-1861","source_learning_sha256":"6ca84b3f8fd122643ae388b0e1a333c410083bb921e478dc930a3fb48ba4f947","source_item_sha256":"a0648bd2dc5429c990252b82648afae432ea8fc0601816bc296a7c74415611c7"},{"item_id":"pilot-serf:manifest-1861","source_learning_sha256":"ad55a1be086eaa54e281e351e5687d7c178e20eaa24ae30b107a1bb8dcb85697","source_item_sha256":"897d03bfefa4f2fbd7efa0d687adf0ccda6a889e956a21a76edd179ee6130fe6"},{"item_id":"pilot-serf:peasant-land-bank-1882","source_learning_sha256":"5ceb0c428c3868ac5cf0b9b4b70af3ad5aec844a4541f48173bc30a08fd9eef9","source_item_sha256":"6bb89af4442ee20797e489a74dd73bf2b3551a2c1dc3859db49dc519f92f5e8f"},{"item_id":"pilot-serf:portugal-1869","source_learning_sha256":"f643cab383ddb6f0985943d1b8e78e6a098225ba67a1286eb2fa164a1181aa75","source_item_sha256":"761cce079ab6f3299a9ebde77ed3e4579ace3b1455277564b86063a2cca55798"},{"item_id":"pilot-serf:previous-peasant-measures","source_learning_sha256":"86053c3314e39fcbda339be821c6aaf1eb659670b014f4545d004c3342eb4131","source_item_sha256":"5129b6df4ce64f704c9641b780a57ace4dc178bb8069107a106ec2431e739cb1"},{"item_id":"pilot-serf:redemption-end-1907","source_learning_sha256":"c02d935334cd68456cf7313bf477c12774317faea7e8dcd5dbd7201f3fd2cad0","source_item_sha256":"028e8d1c87e5db1873109c630aaf96e1b2deba7163307d0fa52019bf56fb9ad4"},{"item_id":"pilot-serf:usa-abolition-1865","source_learning_sha256":"36fbf32b9743c62dfa8425424f8b0dd8b6686f15e1efa7ab328e8514bfecf90a","source_item_sha256":"f4c3ad31f34b52bb5daa29f388d41980d4711053e5423472a0285e6707ff3dc9"},{"item_id":"pilot-serf:year-1855","source_learning_sha256":"01a6cd7b48413011b454f7e6867f495182dabe087fc7b1498166ef2c01472db9","source_item_sha256":"6c8a4a69ae302b6ac5e06fb444f83ec6015f088f3f78d7712c10e48f26d7be74"},{"item_id":"pilot-serf:year-1857","source_learning_sha256":"7549ad551ac97259a9b660c209f999d7346c9ca7a324aa939b295dcbb5b98307","source_item_sha256":"e4965947efd70e361261a83aa5f82788191323a92a6f7ee5e30b99bd24adf87e"},{"item_id":"pilot-serf:year-1858","source_learning_sha256":"e09a80514ede19342b43a8957ee491284c5a6312adf301b3fc750c0c8a90e3d3","source_item_sha256":"5919b6e2a3ca67380107032d5d8893513f44caa6cd28f136da8664dbf53129c7"},{"item_id":"pilot-serf:year-1859","source_learning_sha256":"73c5287d4665ee1412e8abfa3b3bbaee5e07ec955913470cebc61165cfc3ef77","source_item_sha256":"bffd0b071513134af5ea81cca4d19e9999242ea33f509f36115b7c4211b76979"},{"item_id":"pilot-serf:year-1881","source_learning_sha256":"992e9b861ecac9bb319522ec307c7dbe58deaedd05827583e58628c09cf7a0ab","source_item_sha256":"ed39554d3e7714a01ea748bd9f966d0fb578396fc9e022fc7f35c9e8702ff9ee"},{"item_id":"pilot-serf:zemsky-chiefs-1889","source_learning_sha256":"bee12cbe6145fb663fc66981a13452a6fe0c97f98034704e0aaafb71a9eebe4d","source_item_sha256":"352f0a276595968092741d6e5b738ab3296528b2b21bc49893b1ca4fd7f08cfa"}],"source_sections":[{"heading":"Содержание","text":"Земский участковый начальник был назначаемым должностным лицом. Положение 1889 года усилило административный надзор за крестьянскими учреждениями; например, избранные волостные старшины подлежали утверждению земского начальника. Таким образом, выборность внутри крестьянского общества сочеталась с контролем государственной власти.","utf8_sha256":"a0a91d352a13757756585a630dbfecb1cb9f9cc23d94d6c4f23f48ca86ad1b95"},{"heading":"Связь с темой и различия","text":"Этот институт относится к последующей истории устройства крестьянской жизни после 1861 года. Его нельзя смешивать с сельским или волостным сходом, выборным земством либо мировым посредником времени проведения реформы: различаются способ назначения, полномочия и время появления.","utf8_sha256":"5c3919eb0053167af224b2c6869207b90a877c9c2132dc1e99983f0267327f75"}],"additional_saved_quotes":[]},"N04-U01|pilot-serf:redemption-end-1907":{"category_id":"N04-U01","item_id":"pilot-serf:redemption-end-1907","question":"Какое российское событие 1907 года нужно отличать от освобождения 1861 года?","title":"Какое российское событие 1907 года нужно отличать от освобождения 1861 года?","text":"1907 год — отмена выкупных платежей для крестьян. Событие относится к прекращению платежей государству по выкупной операции, а не к изменению личного статуса, оформленному в 1861 году. Указ об обязательном выкупе 1881 года — ещё один отдельный этап. Сохранение трёх соответствий позволяет не смешивать свободу человека, переход на выкуп и прекращение долговых платежей.","gap":"","coverage_status":"bounded_answer","official_category_exact":"Знать ключевые события, основные даты и этапы истории России и мира.","existing_category_rule_exact":"Ключевые события, даты и этапы России и мира. Мировые события из хронологических блоков учебника учитываются отдельно, даже если они не объясняют российскую реформу причинно.","source_learning_sha256":"c02d935334cd68456cf7313bf477c12774317faea7e8dcd5dbd7201f3fd2cad0","source_item_sha256":"028e8d1c87e5db1873109c630aaf96e1b2deba7163307d0fa52019bf56fb9ad4","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"Личная свобода и погашение выкупных обязательств — разные стороны реформы. Манифест 1861 года оформил освобождение, а выкупная операция создала длительные платежные обязательства. Хронология учебника относит отмену выкупных платежей к 1907 году. Поэтому эту дату нельзя подменять датой отмены крепостного права.","utf8_sha256":"006d3315cb2a9e568677f5a20fa9dd6df19d91e8f92aba96efd4de2551c61ee2"},{"paragraph_1based":2,"text":"Между Манифестом 1861 года и отменой платежей прошло 46 лет. Такое сопоставление показывает длительность последствий выкупной операции, но не означает, что все крестьяне платили одинаковое число лет. Для хронологического задания главное различать освобождение человека, переход на обязательный выкуп и прекращение платежей государству.","utf8_sha256":"2e8de8f78a35873c3cf42bdc593ed3ac312554262f83f6abd8cb08308501e477"},{"paragraph_1based":3,"text":"Между событиями менялся предмет государственного решения: сначала личное положение, затем условия выкупа, затем платежи. Поэтому промежуток 1861–1907 годов показывает продолжительность последствий земельной операции, а не продолжительность крепостной собственности на человека. В ответе полезно назвать и сходство — связь с крестьянским вопросом, — и различие: какой именно вид отношений изменяла каждая мера.","utf8_sha256":"54830c5907feb15eb436480605631c4cf7a45bc24e45cdb79984faca80369f28"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":295,"quote":"1907 г. — отмена выкупных платежей для крестьян","quote_sha256":"db8ea3144d1e4ec65bf4adc30d0d058bf73eab82d59b92c30797974f080ba711","source_type":"textbook","source_records":[]}],"basis":["CARD_LEARNING.pilot-serf:redemption-end-1907.paragraphs","CARD_DATA.items.pilot-serf:redemption-end-1907.materials","CARD_LEARNING.pilot-serf:redemption-end-1907.sections"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"context_items":[{"item_id":"pilot-serf:brazil-1888","source_learning_sha256":"84f11540595b420406a574db7896d255e029769f9c6b8af73bf6074001e1ba15","source_item_sha256":"e9625634e16b8c3452a6516fa143d660625f8b4070f9f812bd5fcd0b1717a568"},{"item_id":"pilot-serf:january-1861","source_learning_sha256":"6ca84b3f8fd122643ae388b0e1a333c410083bb921e478dc930a3fb48ba4f947","source_item_sha256":"a0648bd2dc5429c990252b82648afae432ea8fc0601816bc296a7c74415611c7"},{"item_id":"pilot-serf:manifest-1861","source_learning_sha256":"ad55a1be086eaa54e281e351e5687d7c178e20eaa24ae30b107a1bb8dcb85697","source_item_sha256":"897d03bfefa4f2fbd7efa0d687adf0ccda6a889e956a21a76edd179ee6130fe6"},{"item_id":"pilot-serf:peasant-land-bank-1882","source_learning_sha256":"5ceb0c428c3868ac5cf0b9b4b70af3ad5aec844a4541f48173bc30a08fd9eef9","source_item_sha256":"6bb89af4442ee20797e489a74dd73bf2b3551a2c1dc3859db49dc519f92f5e8f"},{"item_id":"pilot-serf:portugal-1869","source_learning_sha256":"f643cab383ddb6f0985943d1b8e78e6a098225ba67a1286eb2fa164a1181aa75","source_item_sha256":"761cce079ab6f3299a9ebde77ed3e4579ace3b1455277564b86063a2cca55798"},{"item_id":"pilot-serf:previous-peasant-measures","source_learning_sha256":"86053c3314e39fcbda339be821c6aaf1eb659670b014f4545d004c3342eb4131","source_item_sha256":"5129b6df4ce64f704c9641b780a57ace4dc178bb8069107a106ec2431e739cb1"},{"item_id":"pilot-serf:redemption-end-1907","source_learning_sha256":"c02d935334cd68456cf7313bf477c12774317faea7e8dcd5dbd7201f3fd2cad0","source_item_sha256":"028e8d1c87e5db1873109c630aaf96e1b2deba7163307d0fa52019bf56fb9ad4"},{"item_id":"pilot-serf:usa-abolition-1865","source_learning_sha256":"36fbf32b9743c62dfa8425424f8b0dd8b6686f15e1efa7ab328e8514bfecf90a","source_item_sha256":"f4c3ad31f34b52bb5daa29f388d41980d4711053e5423472a0285e6707ff3dc9"},{"item_id":"pilot-serf:year-1855","source_learning_sha256":"01a6cd7b48413011b454f7e6867f495182dabe087fc7b1498166ef2c01472db9","source_item_sha256":"6c8a4a69ae302b6ac5e06fb444f83ec6015f088f3f78d7712c10e48f26d7be74"},{"item_id":"pilot-serf:year-1857","source_learning_sha256":"7549ad551ac97259a9b660c209f999d7346c9ca7a324aa939b295dcbb5b98307","source_item_sha256":"e4965947efd70e361261a83aa5f82788191323a92a6f7ee5e30b99bd24adf87e"},{"item_id":"pilot-serf:year-1858","source_learning_sha256":"e09a80514ede19342b43a8957ee491284c5a6312adf301b3fc750c0c8a90e3d3","source_item_sha256":"5919b6e2a3ca67380107032d5d8893513f44caa6cd28f136da8664dbf53129c7"},{"item_id":"pilot-serf:year-1859","source_learning_sha256":"73c5287d4665ee1412e8abfa3b3bbaee5e07ec955913470cebc61165cfc3ef77","source_item_sha256":"bffd0b071513134af5ea81cca4d19e9999242ea33f509f36115b7c4211b76979"},{"item_id":"pilot-serf:year-1881","source_learning_sha256":"992e9b861ecac9bb319522ec307c7dbe58deaedd05827583e58628c09cf7a0ab","source_item_sha256":"ed39554d3e7714a01ea748bd9f966d0fb578396fc9e022fc7f35c9e8702ff9ee"},{"item_id":"pilot-serf:zemsky-chiefs-1889","source_learning_sha256":"bee12cbe6145fb663fc66981a13452a6fe0c97f98034704e0aaafb71a9eebe4d","source_item_sha256":"352f0a276595968092741d6e5b738ab3296528b2b21bc49893b1ca4fd7f08cfa"}],"source_sections":[{"heading":"Какое обязательство прекратилось","text":"Личная свобода и погашение выкупных обязательств — разные стороны реформы. Манифест 1861 года оформил освобождение, а выкупная операция создала длительные платежные обязательства. Хронология учебника относит отмену выкупных платежей к 1907 году. Поэтому эту дату нельзя подменять датой отмены крепостного права.","utf8_sha256":"006d3315cb2a9e568677f5a20fa9dd6df19d91e8f92aba96efd4de2551c61ee2"},{"heading":"Длительность последствий","text":"Между Манифестом 1861 года и отменой платежей прошло 46 лет. Такое сопоставление показывает длительность последствий выкупной операции, но не означает, что все крестьяне платили одинаковое число лет. Для хронологического задания главное различать освобождение человека, переход на обязательный выкуп и прекращение платежей государству.","utf8_sha256":"2e8de8f78a35873c3cf42bdc593ed3ac312554262f83f6abd8cb08308501e477"},{"heading":"Как читать длительную хронологию","text":"Между событиями менялся предмет государственного решения: сначала личное положение, затем условия выкупа, затем платежи. Поэтому промежуток 1861–1907 годов показывает продолжительность последствий земельной операции, а не продолжительность крепостной собственности на человека. В ответе полезно назвать и сходство — связь с крестьянским вопросом, — и различие: какой именно вид отношений изменяла каждая мера.","utf8_sha256":"54830c5907feb15eb436480605631c4cf7a45bc24e45cdb79984faca80369f28"}],"additional_saved_quotes":[]},"N04-U01|pilot-serf:previous-peasant-measures":{"category_id":"N04-U01","item_id":"pilot-serf:previous-peasant-measures","question":"Какие этапы крестьянской политики Николая I предшествовали реформе Александра II?","title":"Какие этапы крестьянской политики Николая I предшествовали реформе Александра II?","text":"При Николае I обсуждение велось в секретных комитетах; в 1837–1841 годах проведена реформа государственных крестьян, в 1842 году издан Указ об обязанных крестьянах, с 1847 года в западных губерниях вводились инвентари. Это разные меры по управлению, повинностям и условиям положения крестьян, а не общая отмена помещичьей зависимости. Для ориентира нужно сохранять группу населения и предмет каждой меры.","gap":"Спорное учебниковое число освобождённых по указам 1803 и 1842 годов как установленный итог не используется.","coverage_status":"bounded_example_with_explicit_scope","official_category_exact":"Знать ключевые события, основные даты и этапы истории России и мира.","existing_category_rule_exact":"Ключевые события, даты и этапы России и мира. Мировые события из хронологических блоков учебника учитываются отдельно, даже если они не объясняют российскую реформу причинно.","source_learning_sha256":"86053c3314e39fcbda339be821c6aaf1eb659670b014f4545d004c3342eb4131","source_item_sha256":"5129b6df4ce64f704c9641b780a57ace4dc178bb8069107a106ec2431e739cb1","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"Учебник сообщает о более чем 300 указах 1826–1855 годов, касавшихся отношений помещиков и крестьян. В 1826–1849 годах действовали девять секретных комитетов по крестьянскому делу. Обсуждение показывало признание проблемы, но само создание комитетов не изменяло статус всех крепостных.","utf8_sha256":"6607167bcd924438180f469e45cacf910bd18b6ec872180a93416fbe5cd67200"},{"paragraph_1based":2,"text":"В 1842 году был издан Указ об обязанных крестьянах; с 1847 года в западных губерниях вводились инвентари — определение повинностей крестьян в пользу помещика. Реформа государственных крестьян 1837–1841 годов улучшала управление другой категорией населения и потому не равнялась освобождению помещичьих крепостных.","utf8_sha256":"358b12d66b06bd8cfb973d1499a799e21bb7f5d147038d5cb78275a61bc8a106"},{"paragraph_1based":3,"text":"Полная отмена означала столкновение с интересами дворянства и риском потрясений. Поэтому меры оставались частичными. При анализе Манифеста 1861 года их можно привести как примеры предшествующих попыток, различая регулирование повинностей, изменение управления и общую отмену личной зависимости.","utf8_sha256":"041a2a50ad26a16fc4cede59a88682c93dd2b8cb87b7cce44d318ea5aea51c35"},{"paragraph_1based":4,"text":"Фраза учебника об освобождении обязанных крестьян «без земли» требует уточнения: речь о непередаче земли в собственность, а не об отсутствии надела в пользовании. По указу 1842 года помещик сохранял собственность, крестьянин получал участок за согласованные повинности. Это подтверждается текстом указа и публикацией Президентской библиотеки. Указанное на странице 17 число 1 млн 600 тыс. освобождённых по указам 1803 и 1842 годов до 1855 года отдельно не подтверждено. Оно сохранено как спорное сообщение источника и не предлагается для заучивания.","utf8_sha256":"5c02503c007dcd5d796022fbcdd9c48e78d992731dc0bad5c45d6ae44cb33657"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":17,"quote":"С 1826 по 1855 г. было издано более 300 указов","quote_sha256":"c2eaae2914d6cc2dd103cdbe44e246375453467afb6fef08a7adf3bd047985fe","source_type":"textbook","source_records":[]},{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":17,"quote":"В период с 1826 по 1849 г. действовало девять секретных комитетов по крестьянскому делу","quote_sha256":"520ea3452a81e68f95c5812c0da0c279411d875cd5901cf1ae74760ae85188bd","source_type":"textbook","source_records":[]},{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":17,"quote":"Начиная с 1847 г. инвентари были введены в западных губерниях","quote_sha256":"7003766a53942c852e4400ffbed1cb13da2deb96131ad267850b196230f68414","source_type":"textbook","source_records":[]}],"basis":["CARD_LEARNING.pilot-serf:previous-peasant-measures.paragraphs","CARD_DATA.items.pilot-serf:previous-peasant-measures.materials","CARD_LEARNING.pilot-serf:previous-peasant-measures.sections"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"context_items":[{"item_id":"pilot-serf:brazil-1888","source_learning_sha256":"84f11540595b420406a574db7896d255e029769f9c6b8af73bf6074001e1ba15","source_item_sha256":"e9625634e16b8c3452a6516fa143d660625f8b4070f9f812bd5fcd0b1717a568"},{"item_id":"pilot-serf:january-1861","source_learning_sha256":"6ca84b3f8fd122643ae388b0e1a333c410083bb921e478dc930a3fb48ba4f947","source_item_sha256":"a0648bd2dc5429c990252b82648afae432ea8fc0601816bc296a7c74415611c7"},{"item_id":"pilot-serf:manifest-1861","source_learning_sha256":"ad55a1be086eaa54e281e351e5687d7c178e20eaa24ae30b107a1bb8dcb85697","source_item_sha256":"897d03bfefa4f2fbd7efa0d687adf0ccda6a889e956a21a76edd179ee6130fe6"},{"item_id":"pilot-serf:peasant-land-bank-1882","source_learning_sha256":"5ceb0c428c3868ac5cf0b9b4b70af3ad5aec844a4541f48173bc30a08fd9eef9","source_item_sha256":"6bb89af4442ee20797e489a74dd73bf2b3551a2c1dc3859db49dc519f92f5e8f"},{"item_id":"pilot-serf:portugal-1869","source_learning_sha256":"f643cab383ddb6f0985943d1b8e78e6a098225ba67a1286eb2fa164a1181aa75","source_item_sha256":"761cce079ab6f3299a9ebde77ed3e4579ace3b1455277564b86063a2cca55798"},{"item_id":"pilot-serf:previous-peasant-measures","source_learning_sha256":"86053c3314e39fcbda339be821c6aaf1eb659670b014f4545d004c3342eb4131","source_item_sha256":"5129b6df4ce64f704c9641b780a57ace4dc178bb8069107a106ec2431e739cb1"},{"item_id":"pilot-serf:redemption-end-1907","source_learning_sha256":"c02d935334cd68456cf7313bf477c12774317faea7e8dcd5dbd7201f3fd2cad0","source_item_sha256":"028e8d1c87e5db1873109c630aaf96e1b2deba7163307d0fa52019bf56fb9ad4"},{"item_id":"pilot-serf:usa-abolition-1865","source_learning_sha256":"36fbf32b9743c62dfa8425424f8b0dd8b6686f15e1efa7ab328e8514bfecf90a","source_item_sha256":"f4c3ad31f34b52bb5daa29f388d41980d4711053e5423472a0285e6707ff3dc9"},{"item_id":"pilot-serf:year-1855","source_learning_sha256":"01a6cd7b48413011b454f7e6867f495182dabe087fc7b1498166ef2c01472db9","source_item_sha256":"6c8a4a69ae302b6ac5e06fb444f83ec6015f088f3f78d7712c10e48f26d7be74"},{"item_id":"pilot-serf:year-1857","source_learning_sha256":"7549ad551ac97259a9b660c209f999d7346c9ca7a324aa939b295dcbb5b98307","source_item_sha256":"e4965947efd70e361261a83aa5f82788191323a92a6f7ee5e30b99bd24adf87e"},{"item_id":"pilot-serf:year-1858","source_learning_sha256":"e09a80514ede19342b43a8957ee491284c5a6312adf301b3fc750c0c8a90e3d3","source_item_sha256":"5919b6e2a3ca67380107032d5d8893513f44caa6cd28f136da8664dbf53129c7"},{"item_id":"pilot-serf:year-1859","source_learning_sha256":"73c5287d4665ee1412e8abfa3b3bbaee5e07ec955913470cebc61165cfc3ef77","source_item_sha256":"bffd0b071513134af5ea81cca4d19e9999242ea33f509f36115b7c4211b76979"},{"item_id":"pilot-serf:year-1881","source_learning_sha256":"992e9b861ecac9bb319522ec307c7dbe58deaedd05827583e58628c09cf7a0ab","source_item_sha256":"ed39554d3e7714a01ea748bd9f966d0fb578396fc9e022fc7f35c9e8702ff9ee"},{"item_id":"pilot-serf:zemsky-chiefs-1889","source_learning_sha256":"bee12cbe6145fb663fc66981a13452a6fe0c97f98034704e0aaafb71a9eebe4d","source_item_sha256":"352f0a276595968092741d6e5b738ab3296528b2b21bc49893b1ca4fd7f08cfa"}],"source_sections":[{"heading":"Ограничения и проекты","text":"Учебник сообщает о более чем 300 указах 1826–1855 годов, касавшихся отношений помещиков и крестьян. В 1826–1849 годах действовали девять секретных комитетов по крестьянскому делу. Обсуждение показывало признание проблемы, но само создание комитетов не изменяло статус всех крепостных.","utf8_sha256":"6607167bcd924438180f469e45cacf910bd18b6ec872180a93416fbe5cd67200"},{"heading":"Конкретные меры","text":"В 1842 году был издан Указ об обязанных крестьянах; с 1847 года в западных губерниях вводились инвентари — определение повинностей крестьян в пользу помещика. Реформа государственных крестьян 1837–1841 годов улучшала управление другой категорией населения и потому не равнялась освобождению помещичьих крепостных.","utf8_sha256":"358b12d66b06bd8cfb973d1499a799e21bb7f5d147038d5cb78275a61bc8a106"},{"heading":"Предел преобразований","text":"Полная отмена означала столкновение с интересами дворянства и риском потрясений. Поэтому меры оставались частичными. При анализе Манифеста 1861 года их можно привести как примеры предшествующих попыток, различая регулирование повинностей, изменение управления и общую отмену личной зависимости.","utf8_sha256":"041a2a50ad26a16fc4cede59a88682c93dd2b8cb87b7cce44d318ea5aea51c35"},{"heading":"Уточнение земельных условий и числа освобождённых","text":"Фраза учебника об освобождении обязанных крестьян «без земли» требует уточнения: речь о непередаче земли в собственность, а не об отсутствии надела в пользовании. По указу 1842 года помещик сохранял собственность, крестьянин получал участок за согласованные повинности. Это подтверждается текстом указа и публикацией Президентской библиотеки. Указанное на странице 17 число 1 млн 600 тыс. освобождённых по указам 1803 и 1842 годов до 1855 года отдельно не подтверждено. Оно сохранено как спорное сообщение источника и не предлагается для заучивания.","utf8_sha256":"5c02503c007dcd5d796022fbcdd9c48e78d992731dc0bad5c45d6ae44cb33657"}],"additional_saved_quotes":[]}};const a=window.CARD_REVIEWED_APPLICATIONS.answers;for(const k of Object.keys(p)){if(a[k])throw new Error("Unexpected accepted-answer overwrite "+k);}Object.assign(a,p);})();